<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { Download, Refresh, Search, View } from '@element-plus/icons-vue'
import { ElButton, ElDatePicker, ElDescriptions, ElDescriptionsItem, ElDrawer, ElForm, ElFormItem, ElInput, ElMessage, ElOption, ElPagination, ElSelect, ElTable, ElTableColumn, ElTag } from 'element-plus'
import PageHeader from '../components/shell/PageHeader.vue'; import PrototypeStatePanel from '../components/shell/PrototypeStatePanel.vue'
import { satelliteOptions, spaceFileRecords } from '../mocks/dataReception'; import type { PrototypeState } from '../types/prototype'
const params=new URLSearchParams(location.search);const state=(params.get('state')||'normal') as PrototypeState
const filters=reactive({relatedPlan:'',fileName:'',packageName:'',satellite:'',createdRange:[] as string[],predecessorPlan:'',existenceStatus:'',transmissionStatus:''});const applied=ref({...filters,createdRange:[] as string[]});const expanded=ref(false);const pageSize=ref(30);const currentPage=ref(1);const detail=ref<any>(null)
const rows=computed(()=>spaceFileRecords.filter(row=>{const f=applied.value;return(!f.relatedPlan||row.relatedPlan.includes(f.relatedPlan))&&(!f.fileName||row.fileName.includes(f.fileName))&&(!f.packageName||row.packageName.includes(f.packageName))&&(!f.satellite||row.satellite===f.satellite)&&(!f.predecessorPlan||row.predecessorPlan.includes(f.predecessorPlan))&&(!f.existenceStatus||row.existenceStatus===f.existenceStatus)&&(!f.transmissionStatus||row.transmissionStatus===f.transmissionStatus)&&(!f.createdRange.length||(row.createdAt>=f.createdRange[0]&&row.createdAt<=f.createdRange[1]))}))
function query(){applied.value={...filters,createdRange:[...filters.createdRange]};ElMessage.success(`查询完成，当前 ${rows.value.length} 条证据样例`)}function reset(){Object.assign(filters,{relatedPlan:'',fileName:'',packageName:'',satellite:'',createdRange:[],predecessorPlan:'',existenceStatus:'',transmissionStatus:''});applied.value={...filters,createdRange:[]};ElMessage.success('筛选条件已重置')}
</script>
<template><section class="stage-four-page space-file-page"><PageHeader title="星上文件表" description="星上文件与计划关联记录"/><PrototypeStatePanel v-if="state!=='normal'" :state="state" subject="星上文件"/><template v-else>
<div class="filter-panel"><el-form class="filter-form file-filter" label-position="left"><el-form-item label="关联计划号"><el-input v-model="filters.relatedPlan" placeholder="请输入" clearable/></el-form-item><el-form-item label="文件名"><el-input v-model="filters.fileName" placeholder="请输入" clearable/></el-form-item><el-form-item label="数据包名"><el-input v-model="filters.packageName" placeholder="请输入" clearable/></el-form-item><el-form-item label="卫星"><el-select v-model="filters.satellite" placeholder="请选择" clearable><el-option v-for="x in satelliteOptions" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item v-show="expanded" class="date-field" label="创建时间"><el-date-picker v-model="filters.createdRange" type="datetimerange" value-format="YYYY-MM-DD HH:mm:ss" range-separator="至" start-placeholder="开始时间" end-placeholder="结束时间"/></el-form-item><el-form-item v-show="expanded" label="前置计划号"><el-input v-model="filters.predecessorPlan" placeholder="请输入" clearable/></el-form-item><el-form-item v-show="expanded" label="存在状态"><el-select v-model="filters.existenceStatus" placeholder="请选择" clearable><el-option label="计划拍摄" value="计划拍摄"/></el-select></el-form-item><el-form-item v-show="expanded" label="数传状态"><el-select v-model="filters.transmissionStatus" placeholder="请选择" clearable><el-option label="已生成" value="已生成"/><el-option label="已下传" value="已下传"/><el-option label="待安排" value="待安排"/><el-option label="已安排" value="已安排"/></el-select></el-form-item></el-form><div class="filter-actions"><el-button type="primary" :icon="Search" @click="query">查询</el-button><el-button :icon="Refresh" @click="reset">重置</el-button><el-button type="success" plain :icon="Download" @click="ElMessage.success('导出已生成')">导出</el-button></div><button class="expand-filter" type="button" @click="expanded=!expanded">⌄</button></div>
<div class="table-region"><el-table :data="rows" height="100%" class="requirement-table"><el-table-column type="index" label="序号" width="62" fixed="left"/><el-table-column prop="id" label="文件记录编号" min-width="190" fixed="left"/><el-table-column prop="fileName" label="文件名" min-width="145"/><el-table-column prop="packageName" label="数据包名" min-width="120"/><el-table-column prop="predecessorPlan" label="前置计划" min-width="120"/><el-table-column prop="location" label="位置" min-width="90"/><el-table-column prop="sizeMb" label="文件大小(MB)" min-width="125"/><el-table-column label="存在状态" min-width="110"><template #default="{row}"><el-tag effect="plain">{{row.existenceStatus}}</el-tag></template></el-table-column><el-table-column label="数传状态" min-width="105"><template #default="{row}"><el-tag type="success" effect="light">{{row.transmissionStatus}}</el-tag></template></el-table-column><el-table-column prop="relatedPlan" label="关联计划" min-width="110"/><el-table-column prop="satellite" label="卫星" min-width="90"/><el-table-column prop="createdAt" label="创建时间" min-width="165"/><el-table-column prop="updatedAt" label="更新时间" min-width="165"/><el-table-column label="操作" width="70" fixed="right"><template #default="{row}"><el-button link type="primary" :icon="View" title="查看" aria-label="查看星上文件" @click="detail=row"/></template></el-table-column></el-table></div><div class="pagination-bar"><el-pagination v-model:current-page="currentPage" v-model:page-size="pageSize" background layout="total, sizes, prev, pager, next, jumper" :total="397" :page-sizes="[10,30,50,100,200]"/></div>
</template><el-drawer :model-value="!!detail" title="星上文件详情" size="520px" @close="detail=null"><el-alert title="仅展示列表已确认字段，专用详情页字段待确认" type="info" :closable="false" show-icon/><el-descriptions v-if="detail" class="evidence-descriptions" :column="1" border><el-descriptions-item label="文件记录编号">{{detail.id}}</el-descriptions-item><el-descriptions-item label="文件名">{{detail.fileName}}</el-descriptions-item><el-descriptions-item label="数据包名">{{detail.packageName}}</el-descriptions-item><el-descriptions-item label="位置">{{detail.location}}</el-descriptions-item><el-descriptions-item label="文件大小">{{detail.sizeMb}} MB</el-descriptions-item><el-descriptions-item label="卫星">{{detail.satellite}}</el-descriptions-item></el-descriptions></el-drawer></section></template>
